/* The bindings are generated by `wails3 generate bindings` and import the
   Wails runtime, so they work as-is. Everything here is the thin layer on top:
   one place that turns a rejected call into a message a person can read. */

import * as App from "../bindings/Cokpyt/app.js";

function message(error) {
  if (typeof error === "string" && error) return error;
  if (error && typeof error.message === "string" && error.message) return error.message;
  if (error && typeof error.error === "string" && error.error) return error.error;
  return "Something went wrong.";
}

async function call(fn, ...args) {
  try {
    return await fn(...args);
  } catch (error) {
    throw new Error(message(error));
  }
}

export const api = {
  bootstrap: () => call(App.Bootstrap),
  scan: () => call(App.Scan),
  scanFolder: (dir) => call(App.ScanFolder, dir),
  chooseFolder: () => call(App.ChooseFolder),
  selectEnvironment: (python) => call(App.SelectEnvironment, python),
  packageCounts: () => call(App.PackageCounts),
  environmentInfo: (python) => call(App.EnvironmentInfo, python),
  operations: () => call(App.Operations),

  packages: (python) => call(App.Packages, python),
  outdated: (python) => call(App.Outdated, python),
  versions: (python, name) => call(App.Versions, python, name),
  /* Every call that starts pip work takes the frontend's id for the run first:
     it is what lets the optimistic record and the App's record be the same
     operation, so it has to reach Go and not be dropped here. */
  install: (id, python, spec) => call(App.Install, id, python, spec),
  installVersion: (id, python, name, version) => call(App.InstallVersion, id, python, name, version),
  upgrade: (id, python, name) => call(App.Upgrade, id, python, name),
  uninstall: (id, python, name) => call(App.Uninstall, id, python, name),
  upgradeMany: (id, python, names) => call(App.UpgradeMany, id, python, names),
  uninstallMany: (id, python, names) => call(App.UninstallMany, id, python, names),

  doctor: (python) => call(App.Doctor, python),
  cleanupScan: (python) => call(App.CleanupScan, python),
  cleanupRun: (id, python, kinds) => call(App.CleanupRun, id, python, kinds),

  search: (query) => call(App.Search, query),
  indexStatus: () => call(App.IndexStatus),
  refreshIndex: () => call(App.RefreshIndex),
  history: () => call(App.History),
  clearHistory: () => call(App.ClearHistory),

  setTheme: (theme) => call(App.SetTheme, theme),
  introSeen: () => call(App.IntroSeen),
  markIntroSeen: () => call(App.MarkIntroSeen),
  checkForUpdate: () => call(App.CheckForUpdate),
  openURL: (url) => call(App.OpenURL, url),
  revealPath: (path) => call(App.RevealPath, path),
};
